using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ResolverCodeCoverageReceiptTests
{
    [Fact]
    public async Task ResolverIsDecoratedWithExcludeFromCodeCoverage()
    {
        const string source = """
            using MessagePack;

            [MessagePackObject]
            public class MyObject
            {
                [Key(0)]
                public int Value { get; set; }
            }

            [GeneratedMessagePackResolver]
            public partial class TestResolver
            {
            }
            """;

        SyntaxTree syntaxTree = CSharpSyntaxTree.ParseText(
            source,
            new CSharpParseOptions(LanguageVersion.CSharp7_3));
        ImmutableArray<MetadataReference> references = await ReferenceAssemblies.Net.Net80.ResolveAsync(
            LanguageNames.CSharp,
            CancellationToken.None);
        references = references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        CSharpCompilation compilation = CSharpCompilation.Create(
            "ResolverCodeCoverageReceipt",
            new[] { syntaxTree },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _);

        GeneratedSourceResult resolverSource = driver.GetRunResult().Results
            .SelectMany(result => result.GeneratedSources)
            .Single(generatedSource => generatedSource.SourceText.ToString().Contains(
                "partial class TestResolver",
                StringComparison.Ordinal));

        Assert.Contains(
            "[global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage]",
            resolverSource.SourceText.ToString());
    }
}
